<?php/** * Data.php Global initialization file * Copyright Michał Sokołowski 2010 * * @author Michał Sokołowski <msokolowski@example.com> */if( !defined('_I_INIT') ) die();// Fix for removed Session functionsfunction session_put(){   $args = func_get_args();   foreach ($args as $key){      $_SESSION[$key]=$GLOBALS[$key];   }}function session_check($key){   return isset($_SESSION[$key]);}function session_clear($key){   unset($_SESSION[$key]);}if ($GLOBALS['config']['global']['session_store'] == 'mysql') {   function _sess_open($save_path, $session_name) {      return true;   }   function _sess_close() {      return true;   }   function _sess_read($key) {      $value_res = db_query("select value, expiry from " . TBL_CORE_SESSIONS . " where sesskey = '" . db_escape($key) . "'  and active = '1'");      if( db_rows($value_res) ) {         $value = db_fetch_array($value_res);         if( $value['expiry'] < time() ) {            $expiry = time() +  $GLOBALS['config']['global']['session_active'];            db_query("update " . TBL_CORE_SESSIONS . " set active = '0', sesskey = CONCAT(sesskey, '_old_', init) where active = '1' and expiry < '" . time() . "'");            return false;         } else {            if ( isset($value['value']) &&            ( substr_count($value['value'], '{') == substr_count($value['value'], '}') ) ) {               return $value['value'];            }         }      }      return false;   }   function _sess_write($key, $val) {      $expiry = time() +  $GLOBALS['config']['global']['session_active'];      return db_query("insert into " . TBL_CORE_SESSIONS . " (sesskey, active, init, expiry, value) values		('" . db_escape($key) . "', '1', '" . time() . "', '" . db_escape($expiry) . "', '" . db_escape($value) . "')		on duplicate key update expiry = '" . db_escape($expiry) . "', value = '" . db_escape($val) . "'");      db_close();   }   function _sess_destroy($key) {      //return tep_db_query("delete from " . TBL_CORE_SESSIONS . " where sesskey = '" . db_escape($key) . "'");      return db_query("update " . TBL_CORE_SESSIONS . " set active = '0' where sesskey = '" . db_escape($key) . "'");   }   function _sess_gc($maxlifetime) {      //tep_db_query("delete from " . TBL_CORE_SESSIONS . " where expiry < '" . time() . "'");      $purge = time() - $GLOBALS['config']['global']['session_purge'];      db_query("update " . TBL_CORE_SESSIONS . " set active = '0', sesskey = CONCAT(sesskey, '_old_', init) where expiry < '" . time() . "'");      db_query("delete from " . TBL_CORE_SESSIONS . " where active = '0' and expiry < '" . $purge . "'");      return true;   }   session_set_save_handler('_sess_open', '_sess_close', '_sess_read', '_sess_write', '_sess_destroy', '_sess_gc');}?>